import React, { useEffect, useState } from 'react';
import { Table, Button, Form, Modal, Card, Badge, Row, Col } from 'react-bootstrap';
import api from '../services/api';
import { toast } from 'react-toastify';
import { FaCalendarPlus, FaClock, FaUser, FaCheckCircle, FaTimesCircle } from 'react-icons/fa';

const AdminMeetingScheduler = () => {
  const [meetings, setMeetings] = useState([]);
  const [staffList, setStaffList] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [newMeeting, setNewMeeting] = useState({
    title: '',
    details: '',
    date: new Date().toISOString().split('T')[0],
    time: '10:00 AM',
    assignedTo: ''
  });

  const fetchData = async () => {
    try {
      const [mRes, sRes] = await Promise.all([
        api.get('/meetings'),
        api.get('/admin/staff')
      ]);
      setMeetings(mRes.data);
      setStaffList(sRes.data);
      if (sRes.data.length > 0 && !newMeeting.assignedTo) {
        setNewMeeting(prev => ({ ...prev, assignedTo: sRes.data[0]._id }));
      }
    } catch (err) {
      toast.error('Failed to load meeting or staff data');
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleCreateMeeting = async (e) => {
    e.preventDefault();
    if (!newMeeting.assignedTo) {
      toast.error('Please select a staff member');
      return;
    }
    try {
      await api.post('/meetings', newMeeting);
      toast.success('Meeting scheduled & assigned to staff!');
      setShowModal(false);
      setNewMeeting({
        title: '',
        details: '',
        date: new Date().toISOString().split('T')[0],
        time: '10:00 AM',
        assignedTo: staffList[0]?._id || ''
      });
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to schedule meeting');
    }
  };

  const handleStatusChange = async (id, status) => {
    try {
      await api.put(`/meetings/${id}`, { status });
      toast.success(`Meeting marked as ${status}`);
      fetchData();
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h3 className="fw-bold mb-1">Calendar & Meeting Scheduler</h3>
          <p className="text-muted small mb-0">Assign sales meetings, client demos, and reviews to staff members</p>
        </div>
        <Button className="btn-violet" onClick={() => setShowModal(true)}>
          <FaCalendarPlus className="me-2" /> Schedule Meeting
        </Button>
      </div>

      <Row className="g-3 mb-4">
        <Col md={4}>
          <div className="crm-card p-3 d-flex align-items-center gap-3">
            <div className="d-flex align-items-center justify-content-center bg-primary-subtle text-primary rounded-circle" style={{ width: '48px', height: '48px', fontSize: '20px' }}>
              📅
            </div>
            <div>
              <div className="text-muted small fw-semibold">Total Meetings</div>
              <h4 className="fw-bold mb-0">{meetings.length}</h4>
            </div>
          </div>
        </Col>
        <Col md={4}>
          <div className="crm-card p-3 d-flex align-items-center gap-3">
            <div className="d-flex align-items-center justify-content-center bg-warning-subtle text-warning rounded-circle" style={{ width: '48px', height: '48px', fontSize: '20px' }}>
              ⏳
            </div>
            <div>
              <div className="text-muted small fw-semibold">Scheduled / Pending</div>
              <h4 className="fw-bold mb-0">{meetings.filter(m => m.status === 'scheduled').length}</h4>
            </div>
          </div>
        </Col>
        <Col md={4}>
          <div className="crm-card p-3 d-flex align-items-center gap-3">
            <div className="d-flex align-items-center justify-content-center bg-success-subtle text-success rounded-circle" style={{ width: '48px', height: '48px', fontSize: '20px' }}>
              ✅
            </div>
            <div>
              <div className="text-muted small fw-semibold">Completed</div>
              <h4 className="fw-bold mb-0">{meetings.filter(m => m.status === 'completed').length}</h4>
            </div>
          </div>
        </Col>
      </Row>

      <Card className="crm-card p-4 border-0">
        <Table responsive className="custom-table mb-0">
          <thead>
            <tr>
              <th>Meeting Title</th>
              <th>Assigned Staff</th>
              <th>Date & Time</th>
              <th>Status</th>
              <th className="text-end">Actions</th>
            </tr>
          </thead>
          <tbody>
            {meetings.length === 0 ? (
              <tr>
                <td colSpan="5" className="text-center py-4 text-muted">
                  No meetings scheduled. Click "Schedule Meeting" to assign meetings to staff.
                </td>
              </tr>
            ) : (
              meetings.map((m) => (
                <tr key={m._id}>
                  <td>
                    <div className="fw-bold text-dark">{m.title}</div>
                    <div className="text-muted small">{m.details || 'No additional details'}</div>
                  </td>
                  <td>
                    <div className="d-flex align-items-center gap-2">
                      <div className="crm-avatar-fallback" style={{ width: '32px', height: '32px', fontSize: '13px' }}>
                        {m.assignedTo?.name ? m.assignedTo.name.charAt(0).toUpperCase() : 'S'}
                      </div>
                      <div>
                        <div className="fw-semibold small">{m.assignedTo?.name || 'Unassigned'}</div>
                        <div className="text-muted" style={{ fontSize: '11px' }}>{m.assignedTo?.email}</div>
                      </div>
                    </div>
                  </td>
                  <td>
                    <div className="d-flex align-items-center gap-2 small font-monospace text-dark">
                      <FaClock className="text-muted" />
                      <span>{m.date} | {m.time}</span>
                    </div>
                  </td>
                  <td>
                    {m.status === 'scheduled' && <Badge bg="warning" className="px-3 py-2 rounded-pill">Scheduled</Badge>}
                    {m.status === 'completed' && <Badge bg="success" className="px-3 py-2 rounded-pill">Completed</Badge>}
                    {m.status === 'cancelled' && <Badge bg="danger" className="px-3 py-2 rounded-pill">Cancelled</Badge>}
                  </td>
                  <td className="text-end">
                    {m.status === 'scheduled' && (
                      <div className="d-flex justify-content-end gap-2">
                        <Button variant="outline-success" size="sm" onClick={() => handleStatusChange(m._id, 'completed')}>
                          <FaCheckCircle className="me-1" /> Complete
                        </Button>
                        <Button variant="outline-danger" size="sm" onClick={() => handleStatusChange(m._id, 'cancelled')}>
                          <FaTimesCircle className="me-1" /> Cancel
                        </Button>
                      </div>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </Card>

      {/* Schedule Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} centered>
        <Modal.Header closeButton className="border-0 pb-0">
          <Modal.Title className="fw-bold">Schedule Staff Meeting</Modal.Title>
        </Modal.Header>
        <Modal.Body className="p-4">
          <Form onSubmit={handleCreateMeeting}>
            <Form.Group className="mb-3">
              <Form.Label className="small fw-semibold">Meeting Title</Form.Label>
              <Form.Control 
                required 
                value={newMeeting.title} 
                onChange={e => setNewMeeting({ ...newMeeting, title: e.target.value })} 
                placeholder="e.g. Client Pitch / Weekly Performance Sync"
                style={{ borderRadius: '10px' }}
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label className="small fw-semibold">Assign Staff Member</Form.Label>
              <Form.Select 
                required 
                value={newMeeting.assignedTo} 
                onChange={e => setNewMeeting({ ...newMeeting, assignedTo: e.target.value })}
                style={{ borderRadius: '10px' }}
              >
                {staffList.map(s => (
                  <option key={s._id} value={s._id}>
                    {s.name} ({s.email})
                  </option>
                ))}
              </Form.Select>
            </Form.Group>

            <Row className="g-2 mb-3">
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="small fw-semibold">Date</Form.Label>
                  <Form.Control 
                    type="date"
                    required
                    value={newMeeting.date}
                    onChange={e => setNewMeeting({ ...newMeeting, date: e.target.value })}
                    style={{ borderRadius: '10px' }}
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="small fw-semibold">Time</Form.Label>
                  <Form.Control 
                    type="text"
                    required
                    value={newMeeting.time}
                    onChange={e => setNewMeeting({ ...newMeeting, time: e.target.value })}
                    placeholder="e.g. 11:30 AM"
                    style={{ borderRadius: '10px' }}
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-4">
              <Form.Label className="small fw-semibold">Details / Notes</Form.Label>
              <Form.Control 
                as="textarea"
                rows={3}
                value={newMeeting.details} 
                onChange={e => setNewMeeting({ ...newMeeting, details: e.target.value })} 
                placeholder="Add meeting agenda or instructions..."
                style={{ borderRadius: '10px' }}
              />
            </Form.Group>

            <div className="d-flex justify-content-end gap-2 pt-2">
              <Button variant="secondary" onClick={() => setShowModal(false)} style={{ borderRadius: '10px' }}>Cancel</Button>
              <Button className="btn-violet" type="submit">Assign Meeting</Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>
    </div>
  );
};

export default AdminMeetingScheduler;
